DECLARE @TransIds_bettrans14 VARCHAR(MAX) = '214669371774074907,214671523552690182,214673718280978443,214695687038697480,214712308562133009,214712725173960712,214757929704751136,214758595424681992,214794093329383424,214805698331017248,214854175626887169,215030234926284807,215032829086531599,215044885059731479,215052508626681878,215054480016670756,215055227340980264,215078974215159815,215140950593241114,215156880626941980,215171410501304350,215202518949429251,215207054434893825,215227859256475654,215448912633266181,215469502706483203,215492626810404880,215505954093924390,215517683649609746,215551094200205312,215571100157870083,215580299977818117,215588181242806279,215594847032049680,215596431874981896,215736327549747220,215738440673656843,215787102653120541,215826315704533032,215868324779655191,215888193298366485,215910265135300626,215910509948436486,215917068363497474,215921500769746954,215926963968147457,215929566718328837,215929622552903697,215930052049633286,215933230325432322,215950281345597445'
CREATE TABLE #TransIds_bettrans14 (TransId BIGINT)
INSERT INTO #TransIds_bettrans14 (TransId)
SELECT	val AS TransId
FROM	dbo.f_SplitString(@TransIds_bettrans14, ',')
OPTION (maxrecursion 0)

--Insert into TicketVoiding_VoidedTransaction for bettrans14
DECLARE @ReasonId INT = 0 
INSERT INTO dbo.TicketVoiding_Reason (ReasonEnglish, ReasonChineseSimplified)
SELECT N'Technical Error',N'技术有误'
	
SET @ReasonId = SCOPE_IDENTITY()

INSERT INTO dbo.TicketVoiding_VoidedTransaction (
	TransId
	,MessageId
	,ReasonId
	,MatchId
	,IssueTypeId
	,SubIssueTypeId
	,CustID
	)
SELECT t.TransId
	, 0 AS MessageId
	,@ReasonId
	,0
	,NULL
	,NULL
	,b.CustId
FROM #TransIds_bettrans14 t
	INNER JOIN bettrans14 b WITH (NOLOCK) ON b.transid = t.TransId
